/**
* Middleware to inject Visa Pay SDK headers and audit telemetry into request contexts.
*/
export function visaPayTelemetryMiddleware(req: Request, res: Response, next: NextFunction): void {
  const startTime = process.hrtime();
  const clientIp = req.headers["x-forwarded-for"] || req.socket.remoteAddress;
  const userAgent = req.headers["user-agent"] || "unknown";

  res.on("finish", () => {
    const [seconds, nanoseconds] = process.hrtime(startTime);
    const durationMs = (seconds * 1000) + (nanoseconds / 1000000);

    logger.debug({
      endpoint: req.originalUrl,
      method: req.method,
      statusCode: res.statusCode,
      durationMs: durationMs.toFixed(2),
      clientIp,
      userAgent,
      visaTraceId: req.headers["x-visa-trace-id"] || crypto.randomUUID(),
    }, "Visa Pay Telemetry Audit Event");
  });

  next();
}

